content:
Here are the domain objects:
```json
{
  "domain objects": [
    {
      "name": "Older Person",
      "description": "primary user receiving assistance and guidance",
      "attributes": [
        "Personal Data"
      ]
    },
    {
      "name": "Personal Data",
      "description": "data describing identity and personal details of Older Person",
      "attributes": [
        "Health Data",
        "Emergency Contact"
      ]
    },
    {
      "name": "Health Data",
      "description": "medical and physiological information relevant for care and monitoring",
      "attributes": [
        "Heart Rate",
        "Blood Pressure",
        "Activity Level"
      ]
    },
    {
      "name": "Heart Rate",
      "description": "the rate at which the heart of the person beats"
    },
    {
      "name": "Blood Pressure",
      "description": "statistic of the persons blood pressure"
    },
    {
      "name": "Activity Level",
      "description": "determines how many activities the person is taking on"
    },
    {
      "name": "Emergency Contact",
      "description": "trusted person contacted in case of emergency"
    },
    {
      "name": "Schedule",
      "description": "timeline of planned activities for Older Person"
    },
    {
      "name": "Activity",
      "description": "activity supporting health and wellbeing",
      "attributes": [
        "Exercise",
        "Appointment",
        "Medication Intake",
        "Errand",
        "Social Event",
        "Community Event"
      ]
    },
    {
      "name": "Exercise",
      "description": "physical activity to maintain or improve health"
    },
    {
      "name": "Appointment",
      "description": "scheduled meeting with healthcare or service provider"
    },
    {
      "name": "Medication Intake",
      "description": "event of taking a prescribed medication"
    },
    {
      "name": "Medication",
      "description": "drug prescribed to Older Person"
    },
    {
      "name": "Errand",
      "description": "task performed outside home such as shopping or transport"
    },
    {
      "name": "Social Event",
      "description": "interaction with friends or family"
    },
    {
      "name": "Community Event",
      "description": "organized social or cultural gathering in neighborhood"
    },
    {
      "name": "Social Contact",
      "description": "person close to Older Person for communication or support"
    },
    {
      "name": "Medical Caregiver",
      "description": "professional providing medical support or supervision"
    },
    {
      "name": "Prescribed Routine",
      "description": "structured set of activities recommended by Medical Caregiver"
    },
    {
      "name": "Health Incident",
      "description": "critical situation requiring immediate attention"
    },
    {
      "name": "Alert",
      "description": "notification triggered by emergency or abnormal condition"
    },
    {
      "name": "Guidance",
      "description": "assistance provided to Older Person",
      "attributes": [
        "Health Guidance",
        "Home Environment",
        "Travel Routing"
      ]
    },
    {
      "name": "Health Guidance",
      "description": "information or recommendation for healthy behavior"
    },
    {
      "name": "Home Environment",
      "description": "physical space of Older Person relevant for safety and comfort"
    },
    {
      "name": "Travel Routing",
      "description": "directions and support for navigation or mobility"
    }
  ]
}
```
